// In your element's server code, on this computer: the port and the node key come from the node
const base = `http://127.0.0.1:${port}`
const headers = { 'content-type': 'application/json', 'X-Node-Key': process.env.SETTINGS_SECRET }
// from: the id of your element
await fetch(`${base}/v1/remember`, { method: 'POST', headers, body: JSON.stringify({ text: 'the taxi from the airport cost 40 euro', from: ['my-element'] }) })
const answer = await fetch(`${base}/v1/recall`, { method: 'POST', headers, body: JSON.stringify({ text: 'how much was the taxi?', from: ['my-element'] }) }).then((r) => r.json())
